def fill_framed_rectangles(grid, border_color, fill_color, background_color):
    """Fill the background-colored interiors of fully outlined rectangles.

    A rectangle qualifies when all four edges are border_color and every
    interior cell is background_color. Other cells are left unchanged.
    Returns a new grid.
    """
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    def is_frame(top, left, bottom, right):
        return (
            all(grid[top][c] == border_color for c in range(left, right + 1))
            and all(grid[bottom][c] == border_color for c in range(left, right + 1))
            and all(grid[r][left] == border_color for r in range(top, bottom + 1))
            and all(grid[r][right] == border_color for r in range(top, bottom + 1))
        )

    for top in range(rows - 2):
        for bottom in range(top + 2, rows):
            for left in range(cols - 2):
                for right in range(left + 2, cols):
                    if not is_frame(top, left, bottom, right):
                        continue
                    if all(
                        grid[r][c] == background_color
                        for r in range(top + 1, bottom)
                        for c in range(left + 1, right)
                    ):
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                result[r][c] = fill_color

    return result
```

