from collections import deque


def fill_enclosed_regions(grid, background, replacement):
    """Replace background cells in regions enclosed by non-background cells.

    Regions are connected orthogonally. Any background region touching the
    grid's edge is considered exterior and left unchanged.

    Args:
        grid: Rectangular list of rows containing integer cell colors.
        background: Color to replace in enclosed regions.
        replacement: Color to use for enclosed regions.

    Returns:
        A new grid with enclosed background regions filled.
    """
    result = [row[:] for row in grid]
    height = len(result)
    if not height:
        return result
    width = len(result[0])
    if not width:
        return result

    exterior = set()
    queue = deque()

    for r in range(height):
        for c in (0, width - 1):
            if result[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                queue.append((r, c))
    for c in range(width):
        for r in (0, height - 1):
            if result[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (
                0 <= nr < height
                and 0 <= nc < width
                and result[nr][nc] == background
                and (nr, nc) not in exterior
            ):
                exterior.add((nr, nc))
                queue.append((nr, nc))

    for r in range(height):
        for c in range(width):
            if result[r][c] == background and (r, c) not in exterior:
                result[r][c] = replacement

    return result
```

