def is_valid_arc_grid(grid, min_dim=1, max_dim=30):
    """Return whether grid is a rectangular list of ARC-sized rows with cell values 0–9."""
    if not isinstance(grid, (list, tuple)) or not min_dim <= len(grid) <= max_dim:
        return False
    if not isinstance(grid[0], (list, tuple)):
        return False

    width = len(grid[0])
    if not min_dim <= width <= max_dim:
        return False

    return all(
        isinstance(row, (list, tuple))
        and len(row) == width
        and all(type(cell) is int and 0 <= cell <= 9 for cell in row)
        for row in grid
    )


def component_inventory(grid, background=5, connectivity=4):
    """List non-background connected components with color, cells, bounding box, and mask.

    Coordinates and bounding boxes are zero-indexed. Components are returned in
    raster-scan order. `connectivity` may be 4 or 8.
    """
    if connectivity not in (4, 8):
        raise ValueError("connectivity must be 4 or 8")
    if not is_valid_arc_grid(grid):
        raise ValueError("grid must be a valid ARC grid")

    height, width = len(grid), len(grid[0])
    if connectivity == 4:
        neighbors = ((-1, 0), (1, 0), (0, -1), (0, 1))
    else:
        neighbors = tuple(
            (dr, dc)
            for dr in (-1, 0, 1)
            for dc in (-1, 0, 1)
            if (dr, dc) != (0, 0)
        )

    visited = set()
    components = []

    for row in range(height):
        for col in range(width):
            color = grid[row][col]
            if color == background or (row, col) in visited:
                continue

            visited.add((row, col))
            pending = [(row, col)]
            cells = []

            while pending:
                r, c = pending.pop()
                cells.append((r, c))
                for dr, dc in neighbors:
                    nr, nc = r + dr, c + dc
                    if (
                        0 <= nr < height
                        and 0 <= nc < width
                        and grid[nr][nc] == color
                        and (nr, nc) not in visited
                    ):
                        visited.add((nr, nc))
                        pending.append((nr, nc))

            r0 = min(r for r, _ in cells)
            r1 = max(r for r, _ in cells)
            c0 = min(c for _, c in cells)
            c1 = max(c for _, c in cells)
            cell_set = set(cells)
            mask = [
                "".join("#" if (r, c) in cell_set else "." for c in range(c0, c1 + 1))
                for r in range(r0, r1 + 1)
            ]
            components.append({
                "color": color,
                "count": len(cells),
                "bbox": [r0, r1, c0, c1],
                "cells": [list(cell) for cell in sorted(cells)],
                "mask": mask,
            })

    return components
```

