def shift_two_color_palette(grid):
    """Map the lower of two input colors to the higher, and the higher to 0.

    This captures the demonstrated color-cycle rule: for example, colors 5 and
    7 map to 7 and 0, while colors 5 and 9 map to 9 and 0. The grid must contain
    exactly two distinct colors.
    """
    colors = sorted({cell for row in grid for cell in row})
    if len(colors) != 2:
        raise ValueError(f"Expected exactly two colors, found {colors}")
    mapping = {colors[0]: colors[1], colors[1]: 0}
    return [[mapping[cell] for cell in row] for row in grid]
```

